      const rotMat = getHeroRotationMatrix(t);

      gl.uniform2f(uniforms.resolution, heroCanvas.width, heroCanvas.height);
      gl.uniformMatrix3fv(uniforms.rot, false, new Float32Array(rotMat));
      gl.uniform3fv(uniforms.colorBase, MATERIALS.gold.base);
      gl.uniform3fv(uniforms.colorSpec, MATERIALS.gold.spec);
      gl.uniform1i(uniforms.texFront, 0);
      gl.uniform1i(uniforms.texBack, 1);
      gl.uniform1f(uniforms.time, t);

