      const pitch = 0.32 + Math.sin(edTime * Math.PI * 2) * 0.2;
      const roll = Math.cos(edTime * Math.PI * 2) * 0.12;
      const rotMat = eulerToMat3(yaw, pitch, roll);

      gl.uniform2f(uniforms.resolution, canvas.width, canvas.height);
      gl.uniformMatrix3fv(uniforms.rot, false, new Float32Array(rotMat));
      gl.uniform3fv(uniforms.colorBase, item.mat.base);
      gl.uniform3fv(uniforms.colorSpec, item.mat.spec);
      gl.uniform1i(uniforms.texFront, 0);
      gl.uniform1i(uniforms.texBack, 1);
      gl.uniform1f(uniforms.time, t);

      gl.drawArrays(gl.TRIANGLES, 0, 6);
    }

    // -------------------------------------------------------------
    // Animation Loop & Window Demo API
    // -------------------------------------------------------------
    let isPaused = false;
    let animFrameId = null;
    const LOOP_DURATION = 6000; // 6.0 seconds per complete cycle
    let startTime = performance.now();

    function frame(now) {
      if (isPaused) return;
      const elapsed = (now - startTime) % LOOP_DURATION;
      const t = elapsed / LOOP_DURATION;

      renderHeroAtTime(t);

      for (let i = 0; i < editionContexts.length; i++) {
        renderEdition(editionContexts[i], t);
      }

      animFrameId = requestAnimationFrame(frame);
    }

    // Start Loop
    animFrameId = requestAnimationFrame(frame);

    // EXACT REQUIRED PROGRAMMATIC API FOR AUTOMATED GRADING
    window.demo = {
